    @EventHandler( payloadType=CreateBankEvent.class )
    public void handle( CreateBankEvent event) {
	    LOGGER.info("handling CreateBankEvent - " + event );
	    Bank entity = new Bank();
            entity.setBankId( event.getBankId() );
            entity.setName( event.getName() );
            entity.setLegalName( event.getLegalName() );
            entity.setSwiftBic( event.getSwiftBic() );
            entity.setHeadquartersCountry( event.getHeadquartersCountry() );
            entity.setWebsite( event.getWebsite() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllBank( entity );
    }

