    /**
     * Method to retrieve the Bank via an BankPrimaryKey.
     * @param 	id Long
     * @return 	Bank
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Bank handle( FindBankQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getBankId() );
    }
    
    /**
     * Method to retrieve a collection of all Banks
     *
     * @param	query	FindAllBankQuery 
     * @return 	List<Bank> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Bank> handle( FindAllBankQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindBank,
 * but only if the id matches
 *
 * @param		entity	Bank
 */
	protected void emitFindBank( Bank entity ) {
		LOGGER.info("handling emitFindBank" );
		
	    queryUpdateEmitter.emit(FindBankQuery.class,
	                            query -> query.getFilter().getBankId().equals(entity.getBankId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBank
	 * 
	 * @param		entity	Bank
	 */
	protected void emitFindAllBank( Bank entity ) {
		LOGGER.info("handling emitFindAllBank" );
		
	    queryUpdateEmitter.emit(FindAllBankQuery.class,
	                            query -> true,
	                            entity);
	}

